content:
:root {
  --bg: #f4f6fa;
  --surface: #ffffff;
  --sidebar-bg: #10233f;
  --sidebar-active: #1d3a63;
  --primary: #1f6fb2;
  --primary-dark: #185891;
  --text: #1f2733;
  --text-muted: #6b7787;
  --border: #e3e8ef;
  --success: #1f9d6b;
  --danger: #d64545;
  --warning: #d98a1f;
  --radius: 10px;
  --shadow: 0 1px 3px rgba(16, 35, 63, 0.08), 0 1px 2px rgba(16, 35, 63, 0.04);
  font-family: "Segoe UI", "Microsoft YaHei", "PingFang SC", Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; margin: 0; }
body { background: var(--bg); color: var(--text); font-size: 14px; }
.hidden { display: none !important; }

/* ---------- Boot ---------- */
.boot {
  height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 16px; color: var(--text-muted);
}
.boot-spinner {
  width: 42px; height: 42px; border-radius: 50%;
  border: 4px solid #d7e0ec; border-top-color: var(--primary); animation: spin 0.9s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ---------- Login ---------- */
.login-root { height: 100%; display: flex; align-items: center; justify-content: center;
  background: linear-gradient(135deg, #10233f 0%, #1d3f6b 100%); }
.login-card {
  width: 400px; background: var(--surface); border-radius: 14px; padding: 34px 34px 28px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
}
.login-logo { width: 56px; height: 56px; border-radius: 12px; background: var(--primary); color: #fff;
  display: flex; align-items: center; justify-content: center; font-size: 26px; font-weight: 700; margin: 0 auto 14px; }
.login-card h2 { margin: 0 0 4px; text-align: center; font-size: 20px; }
.login-card .login-sub { text-align: center; color: var(--text-muted); margin: 0 0 22px; font-size: 13px; }
.login-tabs { display: flex; border-bottom: 1px solid var(--border); margin-bottom: 20px; }
.login-tabs button { flex: 1; padding: 10px; background: none; border: none; cursor: pointer; font-size: 14px;
  color: var(--text-muted); border-bottom: 2px solid transparent; }
.login-tabs button.active { color: var(--primary); border-bottom-color: var(--primary); font-weight: 600; }

/* ---------- Forms ---------- */
.field { margin-bottom: 15px; }
.field label { display: block; margin-bottom: 6px; font-size: 13px; color: var(--text); font-weight: 500; }
.input, select.input, textarea.input {
  width: 100%; padding: 9px 11px; border: 1px solid var(--border); border-radius: 8px; font-size: 14px;
  color: var(--text); background: #fff; outline: none; transition: border-color 0.15s, box-shadow 0.15s;
  font-family: inherit;
}
.input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(31, 111, 178, 0.15); }
textarea.input { resize: vertical; min-height: 64px; }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 0 14px; }
.form-hint { font-size: 12px; color: var(--text-muted); margin-top: 4px; }

/* ---------- Buttons ---------- */
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 9px 16px;
  border-radius: 8px; border: 1px solid transparent; font-size: 14px; cursor: pointer; font-family: inherit;
  transition: background 0.15s, border-color 0.15s; white-space: nowrap; }
.btn-primary { background: var(--primary); color: #fff; }
.btn-primary:hover { background: var(--primary-dark); }
.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover { background: #bd3a3a; }
.btn-outline { background: #fff; color: var(--primary); border-color: var(--primary); }
.btn-outline:hover { background: #eef5fb; }
.btn-ghost { background: transparent; color: var(--text-muted); }
.btn-ghost:hover { background: rgba(0, 0, 0, 0.05); color: var(--text); }
.btn-sm { padding: 5px 10px; font-size: 12.5px; border-radius: 6px; }
.btn-block { width: 100%; }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }

/* ---------- App layout ---------- */
.app-root { display: flex; height: 100%; }
.sidebar { width: 232px; background: var(--sidebar-bg); color: #c6d3e4; display: flex; flex-direction: column; flex-shrink: 0; }
.brand { display: flex; align-items: center; gap: 11px; padding: 20px 18px; }
.brand-logo { width: 40px; height: 40px; border-radius: 10px; background: var(--primary); color: #fff;
  display: flex; align-items: center; justify-content: center; font-size: 20px; font-weight: 700; }
.brand-title { color: #fff; font-weight: 700; font-size: 15px; }
.brand-sub { color: #7f93ad; font-size: 11px; margin-top: 2px; }
.nav { flex: 1; padding: 8px 12px; overflow-y: auto; }
.nav-item { display: flex; align-items: center; gap: 10px; padding: 10px 13px; border-radius: 8px; cursor: pointer;
  color: #b7c6da; font-size: 14px; margin-bottom: 3px; border: none; background: none; width: 100%; text-align: left; font-family: inherit; }
.nav-item:hover { background: rgba(255, 255, 255, 0.07); color: #fff; }
.nav-item.active { background: var(--sidebar-active); color: #fff; font-weight: 600; }
.nav-item .nav-ico { width: 18px; text-align: center; }
.nav-group-label { font-size: 11px; color: #6f839d; text-transform: uppercase; letter-spacing: 0.5px; padding: 14px 13px 6px; }
.sidebar-footer { padding: 14px; border-top: 1px solid rgba(255, 255, 255, 0.08); }
.user-chip { display: flex; flex-direction: column; gap: 2px; }
.user-chip .uc-name { color: #fff; font-size: 13px; font-weight: 600; }
.user-chip .uc-role { color: #8297b1; font-size: 11.5px; }

.main { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.topbar { display: flex; align-items: center; justify-content: space-between; padding: 16px 26px;
  background: var(--surface); border-bottom: 1px solid var(--border); }
.page-title { margin: 0; font-size: 18px; }
.topbar-actions { display: flex; gap: 8px; }
.view { flex: 1; padding: 24px 26px; overflow-y: auto; }

/* ---------- Cards / stats ---------- */
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 20px; margin-bottom: 20px; }
.card-title { margin: 0 0 16px; font-size: 15px; font-weight: 600; }
.stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; margin-bottom: 20px; }
.stat-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 18px 20px; }
.stat-card .stat-label { color: var(--text-muted); font-size: 13px; }
.stat-card .stat-value { font-size: 28px; font-weight: 700; margin-top: 6px; }
.stat-card .stat-ico { float: right; width: 40px; height: 40px; border-radius: 9px; display: flex;
  align-items: center; justify-content: center; font-size: 18px; }
.ico-blue { background: #e7f1fa; color: var(--primary); }
.ico-green { background: #e4f5ee; color: var(--success); }
.ico-orange { background: #fbf0de; color: var(--warning); }
.ico-red { background: #fbe7e7; color: var(--danger); }

.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
@media (max-width: 1100px) { .grid-2 { grid-template-columns: 1fr; } }

/* ---------- Toolbar / table ---------- */
.toolbar { display: flex; gap: 10px; align-items: center; margin-bottom: 16px; flex-wrap: wrap; }
.toolbar .input { width: auto; min-width: 220px; }
.toolbar .spacer { flex: 1; }

.table-wrap { overflow-x: auto; border: 1px solid var(--border); border-radius: var(--radius); background: #fff; }
table.data { width: 100%; border-collapse: collapse; font-size: 13.5px; }
table.data th { background: #f0f4f9; text-align: left; padding: 11px 14px; font-weight: 600; color: #33415a;
  border-bottom: 1px solid var(--border); white-space: nowrap; }
table.data td { padding: 10px 14px; border-bottom: 1px solid #eef1f5; vertical-align: middle; }
table.data tr:last-child td { border-bottom: none; }
table.data tr:hover td { background: #f8fafd; }
.table-empty { padding: 36px; text-align: center; color: var(--text-muted); }
.row-actions { display: flex; gap: 6px; justify-content: flex-end; }

/* ---------- Badges ---------- */
.badge { display: inline-block; padding: 3px 9px; border-radius: 20px; font-size: 12px; font-weight: 600; white-space: nowrap; }
.badge-green { background: #e4f5ee; color: var(--success); }
.badge-red { background: #fbe7e7; color: var(--danger); }
.badge-orange { background: #fbf0de; color: var(--warning); }
.badge-blue { background: #e7f1fa; color: var(--primary); }
.badge-gray { background: #eceff3; color: #6b7787; }

/* ---------- Modal ---------- */
.modal-backdrop { position: fixed; inset: 0; background: rgba(16, 35, 63, 0.45); display: flex;
  align-items: center; justify-content: center; z-index: 50; padding: 20px; }
.modal { background: #fff; border-radius: 12px; width: 560px; max-width: 100%; max-height: 90vh;
  display: flex; flex-direction: column; box-shadow: 0 24px 60px rgba(0, 0, 0, 0.25); }
.modal.modal-lg { width: 720px; }
.modal-header { display: flex; align-items: center; justify-content: space-between; padding: 18px 22px;
  border-bottom: 1px solid var(--border); }
.modal-header h3 { margin: 0; font-size: 16px; }
.modal-close { background: none; border: none; font-size: 22px; color: var(--text-muted); cursor: pointer; line-height: 1; }
.modal-body { padding: 22px; overflow-y: auto; }
.modal-footer { display: flex; justify-content: flex-end; gap: 10px; padding: 15px 22px; border-top: 1px solid var(--border); }

/* ---------- Toast ---------- */
.toast-root { position: fixed; top: 20px; right: 20px; z-index: 100; display: flex; flex-direction: column; gap: 10px; }
.toast { min-width: 260px; max-width: 380px; padding: 13px 16px; border-radius: 9px; background: #fff;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15); border-left: 4px solid var(--primary); display: flex;
  justify-content: space-between; gap: 12px; animation: slideIn 0.2s ease; }
.toast.success { border-left-color: var(--success); }
.toast.error { border-left-color: var(--danger); }
.toast .toast-msg { font-size: 13.5px; }
@keyframes slideIn { from { transform: translateX(30px); opacity: 0; } to { transform: none; opacity: 1; } }

/* ---------- Bars ---------- */
.bar-row { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.bar-row .bar-label { width: 130px; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bar-track { flex: 1; height: 18px; background: #eef1f5; border-radius: 5px; overflow: hidden; }
.bar-fill { height: 100%; background: var(--primary); border-radius: 5px; min-width: 2px; }
.bar-value { width: 64px; text-align: right; font-size: 13px; color: var(--text-muted); }

.muted { color: var(--text-muted); }
.text-right { text-align: right; }
.mt-0 { margin-top: 0; }
.desc-list { display: grid; grid-template-columns: 110px 1fr; gap: 10px 14px; font-size: 14px; }
.desc-list dt { color: var(--text-muted); }
.desc-list dd { margin: 0; }
